## 1. Why MapLibre GL JS doesn’t have built‑in contours

MapLibre (and its ancestor Mapbox GL JS) can render a **raster‑DEM** (`type: "raster-dem"`) for hill‑shading, terrain exaggeration, etc., but it does **not** expose the elevation values to the style language. Contour lines are a vector feature, so the only way to get them without a pre‑generated vector tileset is to **generate the vector data yourself in JavaScript** (or WebAssembly) and feed it back to the map as a normal `geojson` source.

---

## 2. Core ingredients

| Ingredient | Typical library / API | What it gives you |
|------------|----------------------|-------------------|
| **DEM tile fetch** | `fetch()` + URL template (`{z}/{x}/{y}`) | Raw bytes (`ArrayBuffer`) |
| **Raster decoder** | `geotiff.js` (for GeoTIFF) <br> `mapbox/terrain-rgb` (for Terrain‑RGB PNG) <br> GDAL compiled to WASM (`gdal.js`) | 2‑D array of elevation values (meters) |
| **Isoline algorithm** | `d3-contour` (marching‑squares) <br> `marchingsquares.js` <br> Turf.js `isolines` (requires point cloud) | GeoJSON `MultiPolygon` or `LineString` contours |
| **Pixel → lng/lat** | Tile bounds math (Web Mercator) | Correct geographic coordinates |
| **Threading / caching** | Web Workers, `Comlink`, IndexedDB, `localforage` | Keep UI smooth, avoid re‑computing |

All of these run **entirely in the browser** – no server side work is required beyond serving the DEM tiles.

---

## 3. Minimal working example (single tile)

> **Assumptions**  
> * You have a raster DEM served as **GeoTIFF** tiles at `https://myserver/tiles/{z}/{x}/{y}.tif`.  
> * You want contours every **100 m** between 0 m and 3000 m.  
> * You are using MapLibre GL JS ≥ 2.0.

```html
<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre + Runtime Contours</title>
  <script src="https://unpkg.com/maplibre-gl@2.4.0/dist/maplibre-gl.js"></script>
  <link href="https://unpkg.com/maplibre-gl@2.4.0/dist/maplibre-gl.css" rel="stylesheet" />
  <script src="https://unpkg.com/geotiff@2.0.6/dist/geotiff.browser.min.js"></script>
  <script src="https://unpkg.com/d3-contour@3.0.1/dist/d3-contour.min.js"></script>
  <style>
    body, html { margin:0; height:100%; }
    #map { width:100%; height:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script>
/* -------------------------------------------------
   1️⃣ Initialise MapLibre
------------------------------------------------- */
const map = new maplibregl.Map({
  container: 'map',
  style: {
    version: 8,
    sources: {
      osm: { type: 'raster', tiles: ['https://a.tile.openstreetmap.org/{z}/{x}/{y}.png'], tileSize: 256 }
    },
    layers: [{ id: 'osm', type: 'raster', source: 'osm' }]
  },
  center: [-122.447303, 37.753574],
  zoom: 13
});

/* -------------------------------------------------
   2️⃣ Helper: convert tile x/y/z → WebMercator bounds
------------------------------------------------- */
function tile2bbox(z, x, y) {
  const n = Math.pow(2, z);
  const lon1 = x / n * 360 - 180;
  const lon2 = (x + 1) / n * 360 - 180;
  const lat1 = (Math.atan(Math.sinh(Math.PI * (1 - 2 * y / n))) * 180 / Math.PI);
  const lat2 = (Math.atan(Math.sinh(Math.PI * (1 - 2 * (y + 1) / n))) * 180 / Math.PI);
  return [lon1, lat2, lon2, lat1]; // [west, south, east, north]
}

/* -------------------------------------------------
   3️⃣ Core: fetch a DEM tile, decode, contour, add layer
------------------------------------------------- */
async function addContoursForTile(z, x, y) {
  const url = `https://myserver/tiles/${z}/${x}/${y}.tif`;
  const resp = await fetch(url);
  if (!resp.ok) { console.warn('No DEM tile at', url); return; }

  const arrayBuffer = await resp.arrayBuffer();
  const tiff = await GeoTIFF.fromArrayBuffer(arrayBuffer);
  const image = await tiff.getImage();
  const [width, height] = image.getWidth(), image.getHeight();

  // 1️⃣ Read elevation values (assume single band, signed 16‑bit)
  const raster = await image.readRasters({ interleave: true });
  const elevation = raster; // Float32Array or Int16Array

  // 2️⃣ Build a 2‑D array for d3‑contour (row‑major)
  const values = new Float32Array(width * height);
  for (let i = 0; i < elevation.length; i++) {
    // Some DEMs use -32768 as nodata – replace with NaN
    const v = elevation[i];
    values[i] = (v === -32768) ? NaN : v;
  }

  // 3️⃣ Generate contours (d3‑contour works on a flat array)
  const thresholds = d3.range(0, 3000 + 1, 100); // 0‑3000 m every 100 m
  const contours = d3.contours()
      .size([width, height])
      .thresholds(thresholds)
      (values);

  // 4️⃣ Convert each contour’s pixel coordinates → lng/lat
  const [west, south, east, north] = tile2bbox(z, x, y);
  const xScale = (east - west) / width;
  const yScale = (north - south) / height; // note: north > south

  const features = contours.map(c => {
    // d3‑contour returns GeoJSON MultiPolygon with coordinates in pixel space.
    // We need to re‑project each point.
    const transformed = {
      type: 'Feature',
      properties: { elevation: c.value },
      geometry: {
        type: c.type,
        coordinates: c.coordinates.map(ring => // ring = polygon or multi‑polygon
          ring.map(poly => // poly = linear ring
            poly.map(([px, py]) => [
              west + px * xScale,
              north - py * yScale   // y origin is top‑left in pixel space
            ])
          )
        )
      }
    };
    return transformed;
  });

  // 5️⃣ Add (or replace) a GeoJSON source for this tile
  const sourceId = `contours-${z}-${x}-${y}`;
  if (map.getSource(sourceId)) map.removeSource(sourceId);
  map.addSource(sourceId, {
    type: 'geojson',
    data: {
      type: 'FeatureCollection',
      features
    }
  });

  // 6️⃣ Add a line layer (simple styling)
  const layerId = `contour-lines-${z}-${x}-${y}`;
  if (map.getLayer(layerId)) map.removeLayer(layerId);
  map.addLayer({
    id: layerId,
    type: 'line',
    source: sourceId,
    paint: {
      'line-color': '#000',
      'line-width': [
        'interpolate',
        ['linear'],
        ['zoom'],
        12, 0.5,
        16, 2
      ],
      'line-opacity': 0.7
    }
  });
}

/* -------------------------------------------------
   4️⃣ Hook into map movement – generate contours for
      the visible tiles at a chosen zoom level.
------------------------------------------------- */
function generateContoursForView() {
  const zoom = Math.round(map.getZoom()); // integer zoom for tile grid
  const bounds = map.getBounds();

  // Determine tile range that covers the current view
  const tileRange = (z, lng, lat) => {
    const n = Math.pow(2, z);
    const x = Math.floor((lng + 180) / 360 * n);
    const y = Math.floor(
      (1 - Math.log(Math.tan(lat * Math.PI / 180) + 1 / Math.cos(lat * Math.PI / 180)) / Math.PI) / 2 * n
    );
    return { x, y };
  };

  const tl = tileRange(zoom, bounds.getWest(), bounds.getNorth());
  const br = tileRange(zoom, bounds.getEast(), bounds.getSouth());

  const promises = [];
  for (let x = tl.x; x <= br.x; x++) {
    for (let y = tl.y; y <= br.y; y++) {
      promises.push(addContoursForTile(zoom, x, y));
    }
  }
  // Fire‑and‑forget; you could also await Promise.all(promises) for debugging.
}

/* -------------------------------------------------
   5️⃣ Run once on load, then on moveend (throttled)
------------------------------------------------- */
map.on('load', () => {
  generateContoursForView();
});

let debounceTimer;
map.on('moveend', () => {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(generateContoursForView, 300);
});
</script>
</body>
</html>
```

### What the code does

| Step | What happens |
|------|--------------|
| **Tile fetch**

